export const LOGO_PATH_DATA: string = LOGO_PATHS.join('');

let parsed: PathCommand[] | undefined;

const fmt = (n: number): string => {
  const r = Math.round(n * 1000) / 1000;
  return String(Object.is(r, -0) ? 0 : r);
};

/** The wordmark as one path, scaled by `scale` and moved so its box starts at (x, y). Coordinates round to 0.001. */
export function logoPathData(x: number, y: number, scale: number): string {
  parsed ??= parsePath(LOGO_PATH_DATA);
  let d = '';
  for (const cmd of parsed) {
    d += cmd.c;
    for (let i = 0; i < cmd.v.length; i += 2) {
      d += `${i ? ' ' : ''}${fmt(x + cmd.v[i]! * scale)},${fmt(y + cmd.v[i + 1]! * scale)}`;
    }
  }
  return d;
}
